output_text:
[
  {
    "id": "no_carts_single_file",
    "text": "Carts must not be taken into single-file shelf aisles where shelves line both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_on_foot",
    "text": "An agent may not cross from a wide aisle into a single-file shelf aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cartEntryIntoSingleFile": {
          "pre": {
            "and": [
              "hasCart",
              {
                "not": "singleFileShelfAisle"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntryIntoSingleFile"
    }
  },
  {
    "id": "no_cartless_wandering",
    "text": "Movement without a cart is allowed only at the cart bay, at the mouths of single-file aisles, or inside those single-file aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartBayCorridor": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "permittedNoCartZone": {
          "or": [
            "singleFileShelfAisle",
            "cartAisleMouth",
            "cartBayCorridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "hasCart"
          },
          {
            "not": "permittedNoCartZone"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_open_aisle",
    "text": "When leaving a cart behind, it should be parked only in a wide open aisle, not beside a shelf or in a constricted passage.",
    "abstraction": {
      "state_properties": {
        "wideOpenParking": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideOpenParking"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking or releasing a cart, the agent is obliged to retrieve a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickupCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "pickupCart"
    }
  },
  {
    "id": "cart_required_wide_shelf",
    "text": "Shelf interactions in aisles wider than single-file should be performed with the cart present.",
    "abstraction": {
      "state_properties": {
        "wideShelfServiceZone": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfServiceZone",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "hand_service_single_file",
    "text": "Interactions inside single-file shelf aisles must be done by hand rather than while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "single_file_visit_has_purpose",
    "text": "Upon entering a single-file shelf aisle on foot, the agent is obliged to perform a hand interaction there before leaving the excursion unresolved.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "not": "singleFileShelfAisle"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": {
        "and": [
          "singleFileShelfAisle",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
